def handle(app, svc):
    resp = svc.apply(app)

    # API v2 (current): {"api_version": 2, "result": {"outcome": ..., "credit_limit": int}}
    # Fall back to v1 shape if the partner ever reverts.
    outcome = None
    limit = 0
    if isinstance(resp, dict):
        if isinstance(resp.get("result"), dict):
            outcome = resp["result"].get("outcome")
            limit = resp["result"].get("credit_limit", 0)
        else:
            outcome = resp.get("decision")
            limit = resp.get("limit", 0)
            if outcome == "approve":
                outcome = "approved"
            elif outcome == "refer":
                outcome = "manual_review"
            elif outcome == "decline":
                outcome = "declined"

    # Network rule (spec section 4): self_employed + requested_limit > 6000
    # must go to manual review INSTEAD of being issued. A decline stays a decline.
    if (
        app.get("employment") == "self_employed"
        and isinstance(app.get("requested_limit"), (int, float))
        and app.get("requested_limit") > 6000
    ):
        if outcome == "approved":
            return {"action": "queue_review", "limit": 0}
        # declined or manual_review: leave as-is

    if outcome == "approved":
        return {"action": "issue", "limit": int(limit)}
    if outcome == "declined":
        return {"action": "decline", "limit": 0}
    # manual_review / refer
    return {"action": "queue_review", "limit": 0}

